"""Catálogo de mensagens do idioma (D13, ISSUE-087): o português é a fonte, o inglês a tradução.

O protótipo traduzia o DOM no navegador por um dicionário plano, e o último
registro vencia: "Prazo" virava "Schedule" em todas as telas. Aqui o catálogo
tem **namespace por módulo**, alimentado pelo ``en.js`` do protótipo, e a
tradução acontece no servidor: as telas escrevem português e chamam
``translate`` (ou o ``t``) quando o idioma do request é inglês. Dado cadastrado
não é traduzido — só a interface.

O idioma vive no cookie ``gestnow_idioma`` (``pt`` é o padrão; qualquer outro
valor vale ``pt``). O catalogueiro acrescenta a tradução no namespace da área
que usa o texto; a chave é o texto em português já normalizado (espaços
colapsados), a mesma normalização que a busca faz.

Camadas que usam o catálogo:

* fragmentos e telas — ``t`` e ``idioma`` entram no contexto de
  ``core.responses.AlpineAjaxResponse`` e das telas impressas;
* navegação — ``core.navigation_view.build`` traduz títulos de módulo e tela;
* cliente — ``textos_do_cliente`` leva ao JavaScript da DS só as chaves que os
  arquivos estáticos usam; ``TN.i18n`` as aplica depois de cada view;
* gráficos — ``rotulos_do_grafico`` troca os rótulos padrão do motor;
* exportação — ``Document.idioma`` decide datas e os títulos de Excel/PDF.
"""

from __future__ import annotations

from datetime import date, datetime

import azure.functions as func

LANGUAGE_COOKIE = "gestnow_idioma"
DEFAULT_LANGUAGE = "pt"
SUPPORTED_LANGUAGES = ("pt", "en")
EN = "en"

# Um ano: a escolha é preferência, renovada a cada troca.
COOKIE_MAX_AGE_SECONDS = 365 * 24 * 60 * 60

