def rotulos_do_grafico(language: str) -> dict[str, str]:
    """Os rótulos de interface do motor de gráficos no idioma; vazio em português (o padrão já é PT)."""
    if language != EN:
        return {}
    return {key: translate("graficos", text, language) for key, text in ROTULOS_DO_GRAFICO.items()}


def rotulos_de_grafico(language: str, especificos: dict[str, str] | None = None) -> dict[str, str]:
    """Os rótulos do gráfico para o JSON ``data-dados``: os específicos da tela sobre os do motor."""
    if language != EN:
        return dict(especificos or {})
    return {**rotulos_do_grafico(language), **(especificos or {})}


