def textos_do_cliente(language: str) -> dict[str, dict[str, str]]:
    """O mapa resolvido que o shell entrega a ``TN.i18n``; vazio em português."""
    if language != EN:
        return {}
    return {
        namespace: {key: translate(namespace, key, language) for key in keys}
        for namespace, keys in TEXTOS_DO_CLIENTE.items()
    }
